// src/facets/dash.rs — the facet's own module; src/main.rs adds two lines in FACET WIRING:
//   #[path = "facets/dash.rs"] mod dash;   and   dash::wire(&mut game);
use super::World;
use genex::prelude::*;

#[derive(Default)]
pub struct Dash { x: f32, cooldown: u32, dashes: u32 }

pub fn wire(game: &mut Game<World>) {
    game.facet_state::<Dash>();
    game.on_update(|sim, ctx| {
        let dash = sim.facets.get_mut::<Dash>();
        dash.cooldown = dash.cooldown.saturating_sub(1);
        if (ctx.keys.pressed(Key::Space) || ctx.touches.tapped()) && dash.cooldown == 0 {
            dash.x += ctx.rng.range_f32(2.0, 3.0); // the seeded stream, the same on every destination
            dash.cooldown = 30; // ticks, never wall-clock time
            dash.dashes += 1;
        }
    });
    game.probe("dashes", |sim| json!(sim.facets.get::<Dash>().dashes));
}
